type FleetRecord={id:string;daily_rate_override:number|null;deposit_override:number|null;vehicle_models:{manufacturer:string;model_name:string;variant:string|null;transmission:string|null;passenger_capacity:number|null;rental_type:string|null;daily_rate_override:number|null;deposit_override:number|null;vehicle_categories:{name:string;daily_rate:number;security_deposit:number;default_rental_type:string;passenger_capacity:number}}|null};
