const peso=(n:number)=>new Intl.NumberFormat("en-PH",{style:"currency",currency:"PHP",maximumFractionDigits:0}).format(n);
const escapeHtml=(value:unknown)=>String(value??"—").replace(/[&<>"']/g,char=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[char]||char));
function invoiceHtml(invoice:any){const money=(n:any)=>peso(Number(n||0)),date=(v:any)=>v?new Date(v).toLocaleString("en-PH",{timeZone:"Asia/Manila",dateStyle:"medium",timeStyle:"short"}):"—";const chargeRows=(invoice.charges||[]).filter((x:any)=>x.status==="POSTED"&&!['PAYMENT','DEPOSIT','REFUND','REVERSAL'].includes(x.type)).map((x:any)=>`<tr><td>${escapeHtml(x.description)}</td><td>${escapeHtml(x.quantity)}</td><td>${escapeHtml(money(x.unit_rate))}</td><td>${escapeHtml(money(x.amount))}</td></tr>`).join("");const paymentRows=(invoice.payments||[]).map((x:any)=>`<tr><td>${escapeHtml(x.receipt_number)}</td><td>${escapeHtml(x.method)}</td><td>${escapeHtml(date(x.received_at))}</td><td>${escapeHtml(money(x.amount))}</td></tr>`).join("");return `<!doctype html><html><head><meta charset="utf-8"><title>${escapeHtml(invoice.invoice_number)}</title><style>@page{size:A4;margin:15mm}*{box-sizing:border-box}body{font-family:Arial,sans-serif;color:#13241e;margin:0;font-size:11px}header{display:flex;justify-content:space-between;border-bottom:3px solid #174f3d;padding-bottom:16px}h1{margin:0;color:#174f3d;font-size:26px}header p{margin:4px 0 0;color:#68766f}.invoice{text-align:right}.invoice b,.invoice span{display:block}.invoice b{font-size:16px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin:22px 0}.box{border:1px solid #dfe4df;padding:13px}.box h2,section h2{margin:0 0 9px;font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:#68766f}.box b,.box span{display:block}.box span{margin-top:4px;color:#526059}table{width:100%;border-collapse:collapse;margin-bottom:20px}th,td{border-bottom:1px solid #dfe4df;padding:9px;text-align:left}th{background:#f4f7f4;text-transform:uppercase;font-size:9px}th:last-child,td:last-child{text-align:right}.totals{margin-left:auto;width:290px;border:1px solid #dfe4df;padding:12px}.totals div{display:flex;justify-content:space-between;padding:6px}.totals .grand{border-top:2px solid #174f3d;margin-top:5px;padding-top:10px;font-size:14px}.balance{color:#b83c32}.paid{color:#174f3d}footer{margin-top:40px;border-top:1px solid #dfe4df;padding-top:12px;color:#68766f;display:flex;justify-content:space-between}.actions{position:fixed;right:18px;bottom:18px}.actions button{border:0;border-radius:6px;background:#174f3d;color:#fff;padding:11px 16px;font-weight:bold}@media print{.actions{display:none}}</style></head><body><header><div><h1>RoadReady</h1><p>Vehicle Rental · Final Transaction Invoice</p></div><div class="invoice"><b>${escapeHtml(invoice.invoice_number)}</b><span>${escapeHtml(date(invoice.generated_at))}</span><span>${escapeHtml(invoice.booking_reference)}</span></div></header><div class="grid"><div class="box"><h2>Billed to</h2><b>${escapeHtml(invoice.customer?.name)}</b><span>${escapeHtml(invoice.customer?.mobile)}</span><span>${escapeHtml(invoice.customer?.email)}</span><span>${escapeHtml(invoice.customer?.address)}</span></div><div class="box"><h2>Rental</h2><b>${escapeHtml(invoice.vehicle?.name)}</b><span>Plate ${escapeHtml(invoice.vehicle?.plate_number)} · Unit ${escapeHtml(invoice.vehicle?.unit_number)}</span><span>Released: ${escapeHtml(date(invoice.schedule?.actual_release_at))}</span><span>Returned: ${escapeHtml(date(invoice.schedule?.actual_return_at))}</span></div></div><section><h2>Charges</h2><table><thead><tr><th>Description</th><th>Qty</th><th>Rate</th><th>Amount</th></tr></thead><tbody>${chargeRows||'<tr><td colspan="4">No posted charges.</td></tr>'}</tbody></table></section><section><h2>Payments and receipts</h2><table><thead><tr><th>Receipt</th><th>Method</th><th>Received</th><th>Amount</th></tr></thead><tbody>${paymentRows||'<tr><td colspan="4">No posted payments.</td></tr>'}</tbody></table></section><div class="totals"><div><span>Total charges</span><b>${escapeHtml(money(invoice.charge_total))}</b></div><div><span>Total paid</span><b>${escapeHtml(money(invoice.paid_total))}</b></div><div class="grand ${Number(invoice.balance_due)>0?'balance':'paid'}"><span>${Number(invoice.balance_due)>0?'Balance due':'Amount due'}</span><b>${escapeHtml(money(invoice.balance_due))}</b></div>${Number(invoice.possible_refund)>0?`<div><span>Possible refund</span><b>${escapeHtml(money(invoice.possible_refund))}</b></div>`:""}</div><footer><span>System-generated final invoice</span><span>All times shown in Asia/Manila</span></footer><div class="actions"><button onclick="window.print()">Print / Save as PDF</button></div></body></html>`}

