 const[step,setStep]=useState(1),[category,setCategory]=useState("All"),[selected,setSelected]=useState<Vehicle|null>(null),[sent,setSent]=useState(false),[menu,setMenu]=useState(false),[fleet,setFleet]=useState<Vehicle[]>([]),[fleetLoading,setFleetLoading]=useState(true),[fleetError,setFleetError]=useState("");
 const[pickupDate,setPickupDate]=useState("2026-09-10"),[pickupTime,setPickupTime]=useState("08:00"),[returnDate,setReturnDate]=useState("2026-09-12"),[returnTime,setReturnTime]=useState("18:00");
 const[firstName,setFirstName]=useState(""),[lastName,setLastName]=useState(""),[mobile,setMobile]=useState(""),[email,setEmail]=useState(""),[address,setAddress]=useState(""),[destination,setDestination]=useState(""),[passengers,setPassengers]=useState(1);
